<template><div class="ops-page"><HeaderBar /><main class="ops-main"><div class="ops-toolbar"><div><span class="ops-eyebrow">LIMITED ACCESS</span><h1>岗位与授权</h1><p class="ops-lead">每份授权限定岗位、资源范围和有效期。申请与审批分离。</p></div><el-button v-if="can('iam.request')" type="primary" @click="open">申请岗位授权</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><OpsIdentityRequests @updated="load" /><section class="ops-panel"><div class="ops-toolbar"><h2>授权申请</h2><el-button size="small" @click="load">刷新</el-button></div><el-table :data="requests" v-loading="loading" empty-text="暂无授权申请"><el-table-column prop="targetEmployeeId" label="员工 ID" min-width="140" /><el-table-column prop="roleCode" label="岗位" min-width="130" /><el-table-column prop="scopeId" label="资源范围" min-width="150" /><el-table-column prop="grantExpiresAt" label="有效期至" min-width="180" /><el-table-column prop="status" label="状态" width="110" /><el-table-column label="操作" width="100"><template slot-scope="s"><el-button v-if="can('iam.approve') && s.row.status === 'PENDING' && s.row.requesterId !== profile.employeeId && s.row.targetEmployeeId !== profile.employeeId" type="text" :disabled="busy" @click="approve(s.row)">审批授权</el-button></template></el-table-column></el-table></section><section class="ops-panel"><h2>员工授权记录</h2><el-table :data="grants"><el-table-column prop="employeeId" label="员工 ID" min-width="160" /><el-table-column prop="roleCode" label="岗位" /><el-table-column prop="scopeId" label="范围" /><el-table-column prop="expiresAt" label="有效期" min-width="160" /><el-table-column prop="status" label="状态" /><el-table-column label="操作"><template slot-scope="s"><el-button v-if="can('iam.revoke') && Number(s.row.status) === 1" type="text" :disabled="busy" @click="revoke(s.row)">撤销授权</el-button></template></el-table-column></el-table></section><section class="ops-panel"><h2>当前账号的有效授权</h2><el-table :data="profile.grants || []"><el-table-column prop="roleCode" label="岗位" /><el-table-column prop="scopeId" label="范围" /><el-table-column label="允许操作"><template slot-scope="s">{{ (s.row.permissions || []).join('、') }}</template></el-table-column></el-table></section><el-dialog title="申请有限岗位授权" :visible.sync="dialog" width="min(540px,92vw)"><el-form label-width="95px"><el-form-item label="员工"><el-select v-model="form.targetEmployeeId" filterable><el-option v-for="employee in employees.filter(item => item.status === 1 && item.id !== profile.employeeId)" :key="employee.id" :value="employee.id" :label="employee.username" /></el-select></el-form-item><el-form-item label="岗位模板"><el-select v-model="form.roleCode"><el-option v-for="item in templates" :key="item.code" :value="item.code" :label="item.code" /></el-select></el-form-item><el-form-item label="授权范围"><span>{{ selectedTemplate ? selectedTemplate.domain : '先选择岗位' }}</span></el-form-item><el-form-item label="有效期至"><el-date-picker v-model="form.expiresAt" type="datetime" placeholder="最长 90 天" /></el-form-item><p class="ops-muted">{{ selectedTemplate ? selectedTemplate.permissions.join('、') : '' }}</p></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="request">提交申请</el-button></span></el-dialog></main></div></template>
<script>
import OpsIdentityRequests from './OpsIdentityRequests.vue';
import HeaderBar from '@/components/HeaderBar.vue';
import { platformRequest } from '@/apis/platform';
import { hasPermission } from '@/security/session';
export default {
  components: { HeaderBar, OpsIdentityRequests }, data() { return { templates: [], employees: [], requests: [], grants: [], loading: false, busy: false, error: '', dialog: false, saveError: '', form: { targetEmployeeId: '', roleCode: '', expiresAt: null } }; },
  computed: { profile() { return this.$store.state.userInfo || {}; }, selectedTemplate() { return this.templates.find(item => item.code === this.form.roleCode); } },
  created() { this.load(); },
  methods: {
    can(permission) { return hasPermission(this.profile, permission); },
    async load() { this.loading = true; this.error = ''; try { const [templates,employees,requests,grants] = await Promise.all(['templates','employees','grant-requests','grants'].map(path => platformRequest('GET',`/ops/iam/${path}`))); this.templates = templates; this.employees = employees; this.requests = requests; this.grants = grants; } catch (error) { this.error = error.message; } finally { this.loading = false; } },
    open() { this.form = { targetEmployeeId: '', roleCode: '', expiresAt: null }; this.saveError = ''; this.dialog = true; },
    async request() { if (this.busy) return; if (!this.selectedTemplate || !this.form.targetEmployeeId || !this.form.expiresAt) { this.saveError = '请选择员工、岗位及授权有效期'; return; } this.busy = true; try { await platformRequest('POST','/ops/iam/grant-requests',{ targetEmployeeId: this.form.targetEmployeeId, roleCode: this.form.roleCode, scopeType: 'PLATFORM', scopeId: this.selectedTemplate.domain, expiresAt: this.form.expiresAt.toISOString() }); this.dialog = false; await this.load(); } catch (error) { this.saveError = error.message; } finally { this.busy = false; } },
    async revoke(row) { if (this.busy) return; try { await this.$confirm('撤销后该员工将失去此岗位权限，确认继续？', '撤销授权', {type:'warning'}); } catch (_) { return; } this.busy=true; try { await platformRequest('DELETE', '/ops/iam/grants/' + encodeURIComponent(row.id)); await this.load(); } catch (error) { this.$message.error(error.message); } finally { this.busy=false; } },
    async approve(row) { try { await this.$confirm(`确认批准 ${row.targetEmployeeId} 的 ${row.roleCode} 岗位授权？`, '审批岗位授权', { type: 'warning' }); } catch (_) { return; } this.busy = true; try { await platformRequest('POST',`/ops/iam/grant-requests/${encodeURIComponent(row.id)}/approve`); await this.load(); } catch (error) { this.$message.error(error.message); } finally { this.busy = false; } },
  },
};
</script>
